package com.example.statusdrafter.service;
import com.example.statusdrafter.entity.User; import com.example.statusdrafter.dto.RegistrationForm; import com.example.statusdrafter.repository.UserRepository; import org.springframework.security.core.userdetails.*; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import java.util.*;
@Service public class UserService implements UserDetailsService { private final UserRepository repo; private final PasswordEncoder encoder; public UserService(UserRepository r,PasswordEncoder e){repo=r;encoder=e;} public UserDetails loadUserByUsername(String u)throws UsernameNotFoundException{User x=repo.findByUsername(u).filter(User::isActive).orElseThrow(()->new UsernameNotFoundException("User not found")); return new org.springframework.security.core.userdetails.User(x.getUsername(),x.getPassword(),List.of(new SimpleGrantedAuthority("ROLE_"+x.getRole().name())));}
 public User register(RegistrationForm f){if(repo.findByUsername(f.getUsername()).isPresent())throw new IllegalArgumentException("Username already exists");if(repo.findByEmail(f.getEmail()).isPresent())throw new IllegalArgumentException("Email already exists");return repo.save(new User(f.getName(),f.getUsername(),f.getEmail(),encoder.encode(f.getPassword()),User.Role.EMPLOYEE));}
 public User byUsername(String u){return repo.findByUsername(u).orElseThrow();} public List<User> all(){return repo.findAll();} public List<User> employees(){return repo.findByRole(User.Role.EMPLOYEE);} public User save(User u){return repo.save(u);} public User create(String name,String username,String email,String password,User.Role role){if(repo.findByUsername(username).isPresent())throw new IllegalArgumentException("Username already exists");if(repo.findByEmail(email).isPresent())throw new IllegalArgumentException("Email already exists");return repo.save(new User(name,username,email,encoder.encode(password),role));} public void delete(Long id){repo.deleteById(id);} public long countEmployees(){return repo.countByRole(User.Role.EMPLOYEE);}
}
